import type {SidebarsConfig} from '@docusaurus/plugin-content-docs';

// This runs in Node.js - Don't use client-side code here (browser APIs, JSX...)

/**
 * Two sidebars, each autogenerated from its own docs plugin instance:
 *  - docsSidebar: the task-oriented reference (path ../docs)
 *  - wikiSidebar: the explanatory book (path ../wiki)
 *
 * Folder names map to category labels, so the wiki's numbered directories
 * (1-idea, 2-architecture, …) keep their reading order.
 */
const sidebars: SidebarsConfig = {
  docsSidebar: [{type: 'autogenerated', dirName: '.'}],
  wikiSidebar: [{type: 'autogenerated', dirName: '.'}],
};

export default sidebars;
